mapper.select:
select
dffl.*,
su.nick_name as creatorName
from data_fill_form_log dffl
left join sys_user su on su.username = dffl.commit_by


        and dffl.form_id = #{formId}


        and dffl.operate = #{operate}


        and (dffl.form_id like concat('%', #{keyword}, '%')
        or dffl.commit_by like concat('%', #{keyword}, '%')
        or dffl.description like concat('%', #{keyword}, '%'))


        and dffl.commit_time >= #{beginTime}


        and dffl.commit_time <= #{endTime}


order by dffl.commit_time desc
